"""Bounded SSDeep full-hash parity on generated bytes and explicitly named benign PE."""
import argparse
from concurrent.futures import ThreadPoolExecutor
import hashlib
import json
from pathlib import Path
import random
import sys
import threading
import time

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'backend'))


def cases():
    sizes = {0, 1, 6, 7, 8, 31, 63, 64, 65, 127, 128, 129, 255, 256, 257,
             4095, 4096, 4097, 65535, 65536, 65537, 1024**2 - 1, 1024**2, 1024**2 + 1,
             16 * 1024**2 - 1, 16 * 1024**2}
    for power in (0, 1, 4, 8, 12):
        boundary = 3 * 64 * 2**power
        sizes.update((boundary - 1, boundary, boundary + 1))
    rows = [{'kind': kind, 'size': size} for size in sorted(sizes)
            for kind in ('zero', 'ff', 'cycle', 'random')]
    rng = random.Random(41)
    rows += [{'kind': 'random', 'size': rng.randrange(0, 512 * 1024), 'seed': i + 1} for i in range(64)]
    return rows


def make_bytes(row):
    size = row.get('size', 0)
    if row['kind'] == 'zero':
        return bytes(size)
    if row['kind'] == 'ff':
        return b'\xff' * size
    if row['kind'] == 'cycle':
        return (bytes(range(256)) * (size // 256 + 1))[:size]
    if row['kind'] == 'random':
        return random.Random(row.get('seed', 0)).randbytes(size)
    path = Path(row['path']).resolve()
    allowed = [Path('C:/Windows'), Path(sys.base_prefix)]
    if not any(path.is_relative_to(root.resolve()) for root in allowed):
        raise ValueError('Only installed benign PE paths allowed in parity worker')
    data = path.read_bytes()
    if len(data) > 16 * 1024**2:
        raise ValueError('Parity input budget')
    return data


def worker(bundle):
    from aegisav.scan_process import contain_worker
    contain_worker()
    from aegisav.native_ssdeep import NativeSSDeep, NativeBackendError
    from aegisav.hashes import compute_fuzzy
    import ppdeep
    provider = NativeSSDeep(bundle)
    rows = []
    for case in json.loads(sys.stdin.buffer.read(65536)):
        data = make_bytes(case)
        expected = compute_fuzzy(data)
        observed = compute_fuzzy(data, provider.hash)
        assert expected == observed
        rows.append({**case, 'sha256': hashlib.sha256(data).hexdigest(), 'hashes': observed, 'equal': True})
    if rows:
        data = make_bytes({'kind': 'random', 'size': 65537})
        with ThreadPoolExecutor(max_workers=4) as pool:
            assert list(pool.map(provider.hash, [data] * 8)) == [ppdeep.hash(data)] * 8
        try:
            provider.hash(bytes(16 * 1024**2 + 1))
        except NativeBackendError:
            pass
        else:
            raise AssertionError('Oversize native input accepted')
        output = __import__('ctypes').create_string_buffer(127)
        assert provider.function(b'', 0, output, len(output)) == -1
    print(json.dumps({'report': {'rows': rows, 'concurrent_equal': True,
                               'budget_rejections': True, 'abi': 1}}))


def main():
    from aegisav.scan_process import ProcessScanner
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--bundle', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--resume', type=Path, help='Retain a verified prefix from an interrupted parity run')
    parser.add_argument('--reference-cpu-budget', type=int, choices=(120, 360), default=120,
                        help='Research-only Job CPU allowance for slow pinned Python reference; product unchanged')
    args = parser.parse_args()
    if args.reference_cpu_budget != 120:
        import ctypes
        from ctypes import wintypes as w
        from aegisav import scan_process
        original_job = scan_process.create_job
        class Basic(ctypes.Structure):
            _fields_ = [('process_time', ctypes.c_longlong), ('job_time', ctypes.c_longlong), ('flags', w.DWORD),
                        ('min_ws', ctypes.c_size_t), ('max_ws', ctypes.c_size_t), ('processes', w.DWORD),
                        ('affinity', ctypes.c_size_t), ('priority', w.DWORD), ('scheduling', w.DWORD)]
        class Extended(ctypes.Structure):
            _fields_ = [('basic', Basic), ('io', ctypes.c_ulonglong * 6), ('process_memory', ctypes.c_size_t),
                        ('job_memory', ctypes.c_size_t), ('peak_process', ctypes.c_size_t), ('peak_job', ctypes.c_size_t)]
        def research_job(memory):
            api, handle, name = original_job(memory)
            info = Extended()
            api.QueryInformationJobObject.argtypes = [w.HANDLE, ctypes.c_int, ctypes.c_void_p, w.DWORD, ctypes.c_void_p]
            api.QueryInformationJobObject.restype = w.BOOL
            try:
                if not api.QueryInformationJobObject(handle, 9, ctypes.byref(info), ctypes.sizeof(info), None):
                    raise ctypes.WinError(ctypes.get_last_error())
                info.basic.process_time = args.reference_cpu_budget * 10_000_000
                if not api.SetInformationJobObject(handle, 9, ctypes.byref(info), ctypes.sizeof(info)):
                    raise ctypes.WinError(ctypes.get_last_error())
                return api, handle, name
            except Exception:
                api.CloseHandle(handle)
                raise
        scan_process.create_job = research_job
    if args.output.exists():
        raise ValueError('Retain previous evidence')
    args.output.parent.mkdir(parents=True, exist_ok=True)
    samples = cases()
    samples += [{'kind': 'installed_pe', 'path': str(path)} for path in (
        Path('C:/Windows/System32/notepad.exe'), Path('C:/Windows/SysWOW64/notepad.exe'),
        Path('C:/Windows/System32/kernel32.dll'), Path('C:/Windows/SysWOW64/kernel32.dll'),
        Path('C:/Windows/System32/shell32.dll'), Path(sys.base_prefix) / 'python312.dll',
        Path('C:/Windows/Microsoft.NET/Framework/v4.0.30319/csc.exe'))]
    code = f'from experiments.validate_native_candidate import worker; worker({str(args.bundle.resolve())!r})'
    scanner = ProcessScanner([str(ROOT / '.venv/Scripts/python.exe'), '-B', '-c', code], memory_bytes=512 * 1024**2)
    result = {'completed': False, 'cases': [], 'raw_malware': False,
              'runner_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
              'bundle': json.loads((args.bundle / 'manifest.json').read_text()),
              'reference_job_cpu_seconds': args.reference_cpu_budget, 'job_memory_bytes': 512 * 1024**2}
    if args.resume:
        prior = json.loads(args.resume.read_text())
        assert prior['bundle']['sha256'] == result['bundle']['sha256']
        for actual, expected in zip(prior['cases'], samples):
            assert {key: actual[key] for key in expected} == expected and actual['equal']
        result['cases'] = prior['cases']
        result['resumed_from'] = str(args.resume)
        result['previous_runner_sha256'] = prior['runner_sha256']
    try:
        # Large low-entropy inputs can trigger several passes: isolate every case
        # in the ordinary killable Job rather than spending one shared CPU budget.
        for index, case in enumerate(samples[len(result['cases']):], start=len(result['cases'])):
            report = scanner.scan(json.dumps([case]).encode(), threading.Event(),
                                  time.monotonic() + args.reference_cpu_budget + 5)
            result['cases'].extend(report['rows'])
            result.update(concurrent_equal=report['concurrent_equal'], budget_rejections=report['budget_rejections'])
            args.output.write_text(json.dumps(result, indent=2), encoding='utf-8')
            if index % 20 == 0:
                print('PARITY', index + 1, '/', len(samples), flush=True)
        result.update(completed=True, cleanup_confirmed=scanner.healthy and scanner.active_pid is None)
    except Exception as error:
        result.update(exception_type=type(error).__name__, message=str(error))
        raise
    finally:
        args.output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
    print('COMPLETED', len(result['cases']), flush=True)


if __name__ == '__main__':
    main()
